"""Record the reviewed evidence; never turn an unreviewed capture into a pass."""
import argparse,hashlib,json
from pathlib import Path
REPO=Path(__file__).resolve().parents[3];root=REPO/'benchmark-results/vllm-031-upgrade-20261009';q=root/'quality-final'
p=argparse.ArgumentParser();p.add_argument('--reviewed-quality-sha256',required=True);a=p.parse_args()
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
assert sha(q/'cross-version-quality.json')==a.reviewed_quality_sha256
r=json.loads((REPO/'config/experiments/vllm-031-upgrade/production_image.json').read_text());k=json.loads((root/'kernels-final/campaign.json').read_text());s=json.loads((q/'replay-campaign.json').read_text());d=json.loads((q/'cross-version-quality.json').read_text());capture=json.loads((q/'campaign.json').read_text())
assert k['status']=='PASS_NEW_ABI_KERNEL_GATES' and s['status']=='PASS_NEW_IMAGE_MATCHED_STATE_ORIGINAL_TOLERANCES' and capture['status']=='COMPLETE_NEW_IMAGE_REFERENCE_CAPTURE'
assert r['image_id']==k['image_id']==s['image_id']==capture['image_id'] and r['policy_sha256']==s['policy_sha256']
